const { chromium } = require('playwright');
const fs = require('fs');

async function scrapeIMFData() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  try {
    console.log('Navigating to IMF World Economic Outlook Data Mapper...');
    await page.goto('https://www.imf.org/external/datamapper/', { waitUntil: 'networkidle', timeout: 60000 });

    // Wait for the page to load completely
    await page.waitForTimeout(3000);

    console.log('Looking for search functionality...');

    // Try to find and interact with the country search
    const searchSelectors = [
      'input[placeholder*="country"]',
      'input[placeholder*="Country"]',
      'input[type="search"]',
      'input[placeholder*="Search"]',
      'input.search-input',
      '[data-testid="country-search"]'
    ];

    let found = false;
    for (const selector of searchSelectors) {
      const element = await page.$(selector);
      if (element) {
        console.log(`Found search input with selector: ${selector}`);
        await element.click();
        await element.type('Georgia', { delay: 100 });
        await page.waitForTimeout(1000);
        found = true;
        break;
      }
    }

    if (!found) {
      console.log('Could not find search input. Attempting alternative approach...');
    }

    // Look for Georgia in dropdown or list
    const georgiaOption = await page.$('text=Georgia');
    if (georgiaOption) {
      console.log('Found Georgia option, clicking...');
      await georgiaOption.click();
      await page.waitForTimeout(2000);
    }

    // Take a screenshot to see the current state
    await page.screenshot({ path: '/root/imf_after_search.png' });
    console.log('Screenshot saved: imf_after_search.png');

    // Look for variable selection options
    console.log('Looking for variable options...');

    // Check for Real GDP variables
    const allText = await page.textContent('body');

    if (allText.includes('Real GDP')) {
      console.log('Found "Real GDP" text on page');
    }

    // Try to find and click on Real GDP options
    const gdpConstantSelectors = [
      'text=Real GDP (constant prices, National currency)',
      'text=Real GDP growth',
      'button:has-text("Real GDP")'
    ];

    console.log('Attempting to select GDP variables...');

    // Get all available data
    const pageData = await page.evaluate(() => {
      return {
        title: document.title,
        url: window.location.href,
        bodyText: document.body.innerText.substring(0, 2000)
      };
    });

    console.log('Page Title:', pageData.title);
    console.log('Current URL:', pageData.url);
    console.log('Page content preview:');
    console.log(pageData.bodyText);

    await page.screenshot({ path: '/root/imf_full_page.png' });
    console.log('Full page screenshot saved: imf_full_page.png');

  } catch (error) {
    console.error('Error during scraping:', error.message);
  } finally {
    await browser.close();
  }
}

scrapeIMFData();

const { chromium } = require('playwright');
const fs = require('fs');

async function scrapeIMFData() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  try {
    console.log('Navigating to IMF World Economic Outlook Data Mapper...');
    // Use load instead of networkidle due to heavy JavaScript
    await page.goto('https://www.imf.org/external/datamapper/', { waitUntil: 'load', timeout: 90000 });

    console.log('Page loaded, waiting for dynamic content...');
    await page.waitForTimeout(5000);

    // Get page information
    const pageInfo = await page.evaluate(() => {
      return {
        title: document.title,
        url: window.location.href,
        hasCountrySearch: !!document.querySelector('[placeholder*="country"], [placeholder*="Country"], input[type="search"]')
      };
    });

    console.log('Page loaded successfully');
    console.log('Title:', pageInfo.title);
    console.log('Has country search:', pageInfo.hasCountrySearch);

    // Take a screenshot to see the current state
    await page.screenshot({ path: '/root/imf_loaded.png' });
    console.log('Screenshot saved: imf_loaded.png');

    // Try multiple approaches to find search input
    console.log('Attempting to find and use search functionality...');

    // Approach 1: Direct input search
    const inputs = await page.locator('input').all();
    console.log(`Found ${inputs.length} input elements on the page`);

    for (let i = 0; i < Math.min(5, inputs.length); i++) {
      const placeholder = await inputs[i].getAttribute('placeholder');
      const type = await inputs[i].getAttribute('type');
      console.log(`Input ${i}: type=${type}, placeholder=${placeholder}`);
    }

    // Try clicking on any visible search or country selection elements
    const allButtons = await page.locator('button').all();
    console.log(`Found ${allButtons.length} buttons on the page`);

    // Look for elements containing "country" or "select"
    const countryElements = await page.locator('text=/country|Country|select|Select/i').all();
    console.log(`Found ${countryElements.length} country/select related elements`);

    // Try a different approach - look at the page structure
    const pageStructure = await page.evaluate(() => {
      const elements = [];
      document.querySelectorAll('*').forEach(el => {
        if (el.textContent && (el.textContent.includes('Country') || el.textContent.includes('country'))) {
          elements.push({
            tag: el.tagName,
            text: el.textContent.substring(0, 50),
            classes: el.className
          });
        }
      });
      return elements.slice(0, 10);
    });

    console.log('Page structure with Country references:');
    console.log(JSON.stringify(pageStructure, null, 2));

    // Try to find the main data area
    const mainContent = await page.evaluate(() => {
      const text = document.body.innerText.substring(0, 3000);
      return text;
    });

    console.log('Page content preview:');
    console.log(mainContent);

    // Save HTML for inspection
    const html = await page.content();
    fs.writeFileSync('/root/imf_page.html', html);
    console.log('Full HTML saved to imf_page.html');

  } catch (error) {
    console.error('Error during scraping:', error.message);
    console.error('Error stack:', error.stack);
  } finally {
    await browser.close();
  }
}

scrapeIMFData();

