const { chromium } = require('playwright');
const fs = require('fs');

async function scrapeIMFData() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  try {
    console.log('Navigating to IMF World Economic Outlook Data Mapper...');
    await page.goto('https://www.imf.org/external/datamapper/', { waitUntil: 'load', timeout: 90000 });

    console.log('Page loaded, waiting for dynamic content...');
    await page.waitForTimeout(3000);

    // Find the search input and enter Georgia
    console.log('Searching for Georgia...');
    const searchInput = await page.locator('input[placeholder="Search"]').first();
    if (searchInput) {
      await searchInput.click();
      await searchInput.fill('Georgia');
      await page.waitForTimeout(2000);

      // Look for Georgia in the results and click it
      const georgiaOption = await page.locator('text=/^Georgia$/').first();
      if (georgiaOption) {
        console.log('Found Georgia, clicking it...');
        await georgiaOption.click();
        await page.waitForTimeout(3000);
      }
    }

    // Take screenshot after selecting Georgia
    await page.screenshot({ path: '/root/imf_georgia_selected.png' });
    console.log('Screenshot saved: imf_georgia_selected.png');

    // Now we need to find the variables and data
    // The page should now show data for Georgia

    // First, let's check what's displayed
    const pageContent = await page.evaluate(() => {
      return {
        title: document.title,
        bodyText: document.body.innerText.substring(0, 2000)
      };
    });

    console.log('Current title:', pageContent.title);
    console.log('Current content:');
    console.log(pageContent.bodyText);

    // Look for data in the page
    console.log('Extracting data from the page...');

    // Try to find table data or chart data
    const dataContent = await page.evaluate(() => {
      const result = {};

      // Look for any tables
      const tables = document.querySelectorAll('table');
      result.tableCount = tables.length;

      // Look for any divs with data
      const allDivs = document.querySelectorAll('div');
      result.divCount = allDivs.length;

      // Try to find Georgia references
      const bodyText = document.body.innerText;
      const georgiaIndex = bodyText.indexOf('Georgia');
      if (georgiaIndex !== -1) {
        result.georgiaContext = bodyText.substring(Math.max(0, georgiaIndex - 100), georgiaIndex + 500);
      }

      // Look for numbers that might be GDP data
      const numberPattern = /\d+[\d,.]*/g;
      const numbers = bodyText.match(numberPattern);
      result.numbersFound = numbers ? numbers.slice(0, 20) : [];

      return result;
    });

    console.log('Data extraction results:');
    console.log(JSON.stringify(dataContent, null, 2));

    // Try clicking on different variables to see what options are available
    console.log('Looking for variable options...');

    // Check if there's a settings or variables panel
    const settingsPanel = await page.locator('text=/Settings|Variables|Select/i').first();
    if (settingsPanel) {
      console.log('Found settings/variables panel, clicking...');
      await settingsPanel.click();
      await page.waitForTimeout(2000);
    }

    // Take another screenshot
    await page.screenshot({ path: '/root/imf_after_interaction.png' });
    console.log('Screenshot saved: imf_after_interaction.png');

    // Let's try a different approach - looking at the URL structure
    console.log('Checking current URL...');
    const currentUrl = page.url();
    console.log('Current URL:', currentUrl);

    // Try navigating directly to a URL with specific parameters if possible
    // IMF datamapper might use URL parameters for countries and variables

    // Save the full HTML
    const html = await page.content();
    fs.writeFileSync('/root/imf_georgia_page.html', html);
    console.log('Full HTML saved to imf_georgia_page.html');

  } catch (error) {
    console.error('Error during scraping:', error.message);
    console.error('Error stack:', error.stack);
  } finally {
    await browser.close();
  }
}

scrapeIMFData();

