const { chromium } = require('playwright');
const fs = require('fs');

async function scrapeIMFData() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const allData = {};

  try {
    console.log('Fetching IMF data for Georgia...');

    // Try to access the data directly via URL parameters
    // IMF datamapper often uses specific URL patterns for data access

    // First, let's try navigating with country and variable parameters
    const urls = [
      'https://www.imf.org/external/datamapper/?map=NGDP_R&country=GEO', // Real GDP in constant prices
      'https://www.imf.org/external/datamapper/?map=NGDP_RPCH&country=GEO' // Real GDP growth
    ];

    for (let urlIndex = 0; urlIndex < urls.length; urlIndex++) {
      const url = urls[urlIndex];
      console.log(`\nAttempting URL: ${url}`);

      try {
        await page.goto(url, { waitUntil: 'load', timeout: 60000 });
        await page.waitForTimeout(3000);

        // Get the content
        const content = await page.evaluate(() => {
          return {
            title: document.title,
            url: window.location.href,
            bodyText: document.body.innerText.substring(0, 3000)
          };
        });

        console.log('Title:', content.title);
        console.log('URL:', content.url);
        console.log('Content preview:');
        console.log(content.bodyText.substring(0, 500));

        // Look for data in tables
        const tableData = await page.evaluate(() => {
          const tables = [];
          document.querySelectorAll('table').forEach((table, idx) => {
            const rows = [];
            table.querySelectorAll('tr').forEach(tr => {
              const cells = [];
              tr.querySelectorAll('td, th').forEach(cell => {
                cells.push(cell.textContent.trim());
              });
              if (cells.length > 0) rows.push(cells);
            });
            if (rows.length > 0) {
              tables.push({
                index: idx,
                rows: rows.slice(0, 30) // First 30 rows
              });
            }
          });
          return tables;
        });

        console.log('Tables found:', tableData.length);
        if (tableData.length > 0) {
          console.log('First table content:');
          console.log(JSON.stringify(tableData[0], null, 2));
        }

        // Try to find any data attributes or JavaScript objects
        const jsData = await page.evaluate(() => {
          const result = {};

          // Look for common data storage patterns
          if (window.__data) result.__data = window.__data;
          if (window.data) result.data = window.data;
          if (window.appData) result.appData = window.appData;

          // Look for SVG or canvas elements with data
          const svgs = document.querySelectorAll('svg');
          result.svgCount = svgs.length;

          // Look for text content with years and numbers
          const bodyText = document.body.innerText;
          const lines = bodyText.split('\n').filter(l => l.trim());
          result.textLines = lines.slice(0, 50);

          return result;
        });

        console.log('JavaScript data:');
        console.log(JSON.stringify(jsData, null, 2));

      } catch (err) {
        console.error(`Error with URL ${url}:`, err.message);
      }
    }

