        await page.waitForTimeout(3000);
      }
    }

    // Get the page structure to understand how to navigate variables
    const structure = await page.evaluate(() => {
      const result = {
        tabs: [],
        buttons: [],
        inputs: []
      };

      // Get all tab-like elements
      document.querySelectorAll('[role="tab"], .tab, [data-testid*="tab"]').forEach(el => {
        result.tabs.push({
          text: el.textContent,
          visible: el.offsetParent !== null
        });
