const { chromium } = require('playwright');
const fs = require('fs');

async function scrapeIMFData() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  try {
    console.log('Setting up network interception to capture API calls...');
    const apiResponses = [];

    // Intercept network requests
    page.on('response', async (response) => {
      const url = response.url();
      if (url.includes('api') || url.includes('data') || url.includes('json')) {
        apiResponses.push({
          url: url,
          status: response.status()
        });
      }
    });

    console.log('Navigating to IMF datamapper with Georgia and Real GDP Growth...');
    await page.goto('https://www.imf.org/external/datamapper/NGDP_RPCH@WEO', {
      waitUntil: 'load',
      timeout: 60000
    });

    await page.waitForTimeout(3000);

    // Check URL
    const currentUrl = page.url();
    console.log('Current URL:', currentUrl);

    // Look for the chart/data section
    console.log('\nLooking for chart data...');

    // Try to extract data from the SVG chart or visible data
    const chartData = await page.evaluate(() => {
      const result = {
        visible_text: [],
        svg_elements: [],
        canvas_elements: [],
        script_data: []
      };

      // Get visible text with years
      const bodyText = document.body.innerText;
      const lines = bodyText.split('\n');
      result.visible_text = lines.slice(0, 150);

      // Look for SVG text elements that might contain data
      document.querySelectorAll('svg text').forEach(el => {
        result.svg_elements.push(el.textContent.trim());
      });

      // Look for script tags with JSON data
      document.querySelectorAll('script').forEach(script => {
        if (script.textContent && script.textContent.includes('data')) {
          result.script_data.push(script.textContent.substring(0, 500));
        }
      });

      return result;
    });

    console.log('Chart data:');
    console.log('Visible text (first 50 lines):');
    chartData.visible_text.slice(0, 50).forEach(line => console.log(line));

    console.log('\n\nSVG text elements:');
    console.log(chartData.svg_elements.slice(0, 20));

    // Look for data in localStorage or sessionStorage
    const storageData = await page.evaluate(() => {
      return {
        localStorage: JSON.stringify(localStorage),
        sessionStorage: JSON.stringify(sessionStorage)
      };
    });

    console.log('\n\nStorage data length:', storageData.localStorage.length, storageData.sessionStorage.length);

    // Try to interact with the chart to get detailed data
    // Look for an export or download option
    console.log('\n\nLooking for export/download buttons...');
    const buttons = await page.locator('button').all();
    const buttonTexts = [];
    for (let btn of buttons) {
      const text = await btn.textContent();
      if (text) buttonTexts.push(text.trim());
    }
    console.log('Available buttons:', buttonTexts);

    // Look for links
    const links = await page.locator('a').all();
    const linkTexts = [];
    for (let link of links) {
      const text = await link.textContent();
      const href = await link.getAttribute('href');
      if (text) linkTexts.push({ text: text.trim().substring(0, 30), href });
    }
    console.log('Available links:', linkTexts.slice(0, 20));

    // Try to find the actual data container
    const containerData = await page.evaluate(() => {
      const result = {
        divs_with_data: [],
        all_text: document.body.innerText
      };

      // Look for divs that contain year-like data (2000-2027)
      document.querySelectorAll('div').forEach(div => {
        const text = div.textContent;
        if (text && /20\d{2}/.test(text) && text.length < 500) {
          result.divs_with_data.push({
            class: div.className,
            id: div.id,
            text: text.substring(0, 200)
          });
        }
      });

      return result;
    });

    console.log('\n\nDivs with year data:');
    containerData.divs_with_data.slice(0, 10).forEach(div => {
      console.log(`Class: ${div.class}, ID: ${div.id}`);
      console.log(`Text: ${div.text}`);
      console.log('---');
    });

    // Save the full content for inspection
    const html = await page.content();
    fs.writeFileSync('/root/imf_chart_page.html', html);
    console.log('\n\nFull HTML saved to imf_chart_page.html');

  } catch (error) {
    console.error('Error:', error.message);
  } finally {
    await browser.close();
  }
}

