const { chromium } = require('playwright');
const fs = require('fs');

async function scrapeIMFData() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  try {
    console.log('Extracting IMF data for Georgia...\n');

    // Navigate to Real GDP growth rate first
    console.log('1. Fetching Real GDP Growth Rate for Georgia...');
    await page.goto('https://www.imf.org/external/datamapper/NGDP_RPCH@WEO', {
      waitUntil: 'load',
      timeout: 60000
    });
    await page.waitForTimeout(3000);

    // Search for Georgia
    console.log('   Searching for Georgia...');
    const searchInput = await page.locator('input[placeholder="Search"]').first();
    if (searchInput) {
      await searchInput.click();
      await searchInput.fill('Georgia');
      await page.waitForTimeout(2000);

      const georgiaOption = await page.locator('text=/^Georgia$/').first();
      if (georgiaOption) {
        await georgiaOption.click();
        await page.waitForTimeout(3000);
      }
    }

    // Extract chart data from Highcharts
    const growthData = await page.evaluate(() => {
      const result = {
        variable: 'Real GDP Growth Rate',
        country: 'Georgia',
        data: []
      };

      // Try to get data from Highcharts instance
      if (window.Highcharts && window.Highcharts.charts) {
        for (let chart of window.Highcharts.charts) {
          if (chart && chart.series) {
            for (let series of chart.series) {
              if (series.data) {
                result.data = series.data.map(point => ({
                  year: point.category || point.x,
                  value: point.y
                }));
              }
            }
          }
        }
      }

      // If Highcharts didn't work, try looking at SVG text
      if (result.data.length === 0) {
        const allText = document.body.innerText;
        const lines = allText.split('\n');
        result.debug = {
          totalLines: lines.length,
          sampleLines: lines.slice(0, 100)
        };
      }

      return result;
    });

    console.log('   Growth Rate Data extracted:');
    console.log(`   Found ${growthData.data.length} data points`);
    if (growthData.data.length > 0) {
      console.log('   Sample data:', growthData.data.slice(0, 5));
    }

    // Now navigate to Real GDP level (constant prices)
    console.log('\n2. Fetching Real GDP Level (constant prices) for Georgia...');

    // The variable code for Real GDP in constant prices is typically NGDP_R or similar
    const realGDPUrls = [
      'https://www.imf.org/external/datamapper/NGDP_R@WEO',
      'https://www.imf.org/external/datamapper/NGDP@WEO',
      'https://www.imf.org/external/datamapper/NGDPD@WEO'
    ];

    let levelData = { variable: 'Real GDP Level', country: 'Georgia', data: [] };

    for (const url of realGDPUrls) {
      console.log(`   Trying URL: ${url.split('/').pop()}`);
      try {
        await page.goto(url, { waitUntil: 'load', timeout: 60000 });
        await page.waitForTimeout(2000);

        // Search for Georgia again
        const search2 = await page.locator('input[placeholder="Search"]').first();
        if (search2) {
          await search2.click();
          await search2.fill('Georgia');
          await page.waitForTimeout(2000);

          const georgia2 = await page.locator('text=/^Georgia$/').first();
          if (georgia2) {
            await georgia2.click();
            await page.waitForTimeout(2000);
          }
        }

        // Extract data
        levelData = await page.evaluate(() => {
          const result = {
            variable: 'Real GDP Level',
            country: 'Georgia',
            data: []
          };

          if (window.Highcharts && window.Highcharts.charts) {
            for (let chart of window.Highcharts.charts) {
              if (chart && chart.series) {
                for (let series of chart.series) {
                  if (series.data) {
                    result.data = series.data.map(point => ({
                      year: point.category || point.x,
                      value: point.y
                    }));
                  }
                }
              }
            }
          }

          return result;
        });

        if (levelData.data.length > 0) {
          console.log(`   Found data with ${levelData.data.length} points`);
          break;
        }
      } catch (err) {
        console.log(`   Failed with error: ${err.message.substring(0, 50)}`);
      }
    }

    // Compile all data for 2000-2027
    console.log('\n\n3. COMPILING DATA FOR 2000-2027...\n');

    const startYear = 2000;
    const endYear = 2027;
    const compiledData = [];

    // Filter growth data for 2000-2027
    const growthByYear = {};
    if (growthData.data && growthData.data.length > 0) {
      growthData.data.forEach(item => {
        if (item.year && item.value !== null && item.value !== undefined) {
          const year = parseInt(item.year);
          if (year >= startYear && year <= endYear) {
            growthByYear[year] = item.value;
          }
        }
      });
    }

    // Filter level data for 2000-2027
    const levelByYear = {};
    if (levelData.data && levelData.data.length > 0) {
      levelData.data.forEach(item => {
        if (item.year && item.value !== null && item.value !== undefined) {
          const year = parseInt(item.year);
          if (year >= startYear && year <= endYear) {
            levelByYear[year] = item.value;
          }
        }
      });
    }

    // Combine data
    for (let year = startYear; year <= endYear; year++) {
      compiledData.push({
        year: year,
        real_gdp_level: levelByYear[year] || null,
        real_gdp_growth_rate: growthByYear[year] || null
      });
    }

    // Output in structured format
    console.log('GEORGIA ECONOMIC DATA (2000-2027)');
    console.log('==================================\n');
    console.log('Year\tReal GDP Level\tReal GDP Growth Rate (%)');
    console.log('---\t---------------\t------------------------');

    compiledData.forEach(item => {
      const level = item.real_gdp_level !== null ? item.real_gdp_level.toFixed(2) : 'N/A';
      const growth = item.real_gdp_growth_rate !== null ? item.real_gdp_growth_rate.toFixed(2) : 'N/A';
      console.log(`${item.year}\t${level}\t\t${growth}`);
    });

    // Save to JSON file
    const outputData = {
      country: 'Georgia',
      dataset: 'IMF World Economic Outlook (October 2025)',
      yearRange: { start: startYear, end: endYear },
      data: compiledData,
      generatedAt: new Date().toISOString(),
      sourceUrl: 'https://www.imf.org/external/datamapper/'
    };

    fs.writeFileSync('/root/georgia_gdp_data.json', JSON.stringify(outputData, null, 2));
    console.log('\n\nData saved to: georgia_gdp_data.json');

    // Also save as CSV
    let csvContent = 'Year,Real GDP Level,Real GDP Growth Rate (%)\n';
    compiledData.forEach(item => {
      const level = item.real_gdp_level !== null ? item.real_gdp_level : '';
      const growth = item.real_gdp_growth_rate !== null ? item.real_gdp_growth_rate : '';
      csvContent += `${item.year},${level},${growth}\n`;
    });
    fs.writeFileSync('/root/georgia_gdp_data.csv', csvContent);
    console.log('Data also saved to: georgia_gdp_data.csv');

  } catch (error) {
    console.error('Error during scraping:', error.message);
  } finally {
    await browser.close();
  }
}

scrapeIMFData();

