const { chromium } = require('playwright');
const fs = require('fs');

async function scrapeIMFData() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.createBrowserContext();
  const page = await context.newPage();

  try {
    console.log('Attempting to access IMF API directly for Georgia data...\n');

    // Try direct API calls
    const apiUrls = [
      'https://www.imf.org/external/datamapper/api/v1/series/NGDP_RPCH?countries=GEO&format=json',
      'https://www.imf.org/external/datamapper/api/v1/series/NGDP_R?countries=GEO&format=json',
      'https://data.imf.org/api/datacat/NGDP_RPCH?countries=GEO',
      'https://data.imf.org/api/datacat/NGDP_R?countries=GEO'
    ];

    let dataFound = false;

    for (const apiUrl of apiUrls) {
      console.log(`Trying API: ${apiUrl.substring(0, 80)}...`);
      try {
        const response = await page.request.get(apiUrl);
        if (response.ok()) {
          const data = await response.json();
          console.log('Successfully retrieved data!');
          console.log(JSON.stringify(data, null, 2).substring(0, 1000));
          dataFound = true;
          break;
        }
      } catch (err) {
        console.log(`  Failed: ${err.message.substring(0, 50)}`);
      }
    }

    if (!dataFound) {
      console.log('\nAPI approach failed, falling back to browser automation...\n');

      // Navigate to the datamapper
      console.log('Navigating to IMF Datamapper...');
      await page.goto('https://www.imf.org/external/datamapper/', {
        waitUntil: 'load',
        timeout: 60000
      });
      await page.waitForTimeout(4000);

      // Look for a "Chart" tab and data table
      console.log('Looking for chart view...');

      // Try clicking on "chart" tab if it exists
      const chartTab = await page.locator('input[value="3"]').first();
      if (chartTab) {
        console.log('Found chart tab, clicking...');
        await chartTab.click();
        await page.waitForTimeout(2000);
      }

      // Search for Georgia
      console.log('Searching for Georgia...');
      const searchInput = await page.locator('input[placeholder="Search"]').first();
      if (searchInput) {
        await searchInput.click();
        await searchInput.fill('Georgia');
        await page.waitForTimeout(2000);

        const georgiaOption = await page.locator('text=/^Georgia$/').first();
        if (georgiaOption) {
          await georgiaOption.click();
          await page.waitForTimeout(3000);
        }
      }

      // Look for "selected" tab which might show a table
      const selectedTab = await page.locator('input[value="4"]').first();
      if (selectedTab) {
        console.log('Clicking on selected tab to view data table...');
        await selectedTab.click();
        await page.waitForTimeout(2000);
      }

      // Try to extract the full page content as text
      const tableData = await page.evaluate(() => {
        const result = {
          allText: document.body.innerText,
          tables: [],
          divWithYears: null
        };

        // Look for tables
        document.querySelectorAll('table').forEach((table, idx) => {
          const rows = [];
          table.querySelectorAll('tr').forEach(tr => {
            const cells = [];
            tr.querySelectorAll('td, th').forEach(cell => {
              cells.push(cell.textContent.trim());
            });
            if (cells.length > 0) rows.push(cells);
          });
          if (rows.length > 0) {
            result.tables.push({
              id: idx,
              rowCount: rows.length,
              rows: rows.slice(0, 40)
            });
          }
        });

        // Look for divs with data attributes
        document.querySelectorAll('div').forEach(div => {
          if (div.getAttribute('data-series') || div.getAttribute('data-country') || div.getAttribute('data-data')) {
            if (!result.divWithYears) {
              result.divWithYears = {
                tag: div.tagName,
                attrs: Array.from(div.attributes).map(a => `${a.name}=${a.value}`),
                text: div.textContent.substring(0, 500)
              };
            }
          }
        });

        return result;
      });

      console.log('\nExtracted page content:');
      console.log('Tables found:', tableData.tables.length);

      if (tableData.tables.length > 0) {
        console.log('\nFirst table structure:');
        const firstTable = tableData.tables[0];
        console.log(`Rows: ${firstTable.rowCount}`);
        if (firstTable.rows.length > 0) {
          console.log('Sample rows:');
          firstTable.rows.slice(0, 10).forEach(row => {
            console.log('  ' + row.join(' | '));
          });
        }
      }

      // Parse the text for data
      console.log('\n\nLooking for numerical data in page text...');
      const lines = tableData.allText.split('\n');

      // Filter lines that look like data (year, value pairs)
      const dataLines = lines.filter(line => /20\d{2}|19\d{2}/.test(line) && /\d+\.?\d*/.test(line));
      console.log(`Found ${dataLines.length} potential data lines`);

      if (dataLines.length > 0) {
        console.log('Sample data lines:');
        dataLines.slice(0, 20).forEach(line => console.log('  ' + line));
      }

      // Save for debugging
      fs.writeFileSync('/root/imf_page_text.txt', tableData.allText);
      console.log('\nFull page text saved to imf_page_text.txt');
    }

  } catch (error) {
    console.error('Error:', error.message);
    console.error('Stack:', error.stack);
  } finally {
    await browser.close();
  }
}

