const { chromium } = require('playwright');
const fs = require('fs');

async function scrapeIMFData() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  try {
    const allData = {
      growthRates: {},
      levels: {}
    };

    // Process Real GDP Growth Rate
    console.log('Scraping Real GDP Growth Rate for Georgia...\n');
    await page.goto('https://www.imf.org/external/datamapper/NGDP_RPCH@WEO', {
      waitUntil: 'load',
      timeout: 60000
    });
    await page.waitForTimeout(3000);

    // Search for Georgia
    let searchInput = await page.locator('input[placeholder="Search"]').first();
    if (searchInput) {
      await searchInput.click({ timeout: 5000 });
      await searchInput.fill('Georgia');
      await page.waitForTimeout(1500);

      const georgiaOption = await page.locator('text=/^Georgia$/').first();
      if (georgiaOption) {
        await georgiaOption.click();
        await page.waitForTimeout(3000);
      }
    }

    // Extract visible data from page
    let pageData = await page.evaluate(() => {
      return document.body.innerText;
    });

    // Save for analysis
    fs.writeFileSync('/root/growth_rate_page.txt', pageData);
    console.log('Growth rate page saved. Analyzing...\n');

    // Parse the growth rate data
    let lines = pageData.split('\n');
    console.log('Sample of extracted text:');
    lines.slice(20, 60).forEach(line => console.log(line));

    // Look for Georgia's data in the table
    const georgiaIndex = lines.findIndex(line => line.includes('Georgia') && !line.includes('South'));
    if (georgiaIndex !== -1) {
      console.log(`\nFound Georgia at line ${georgiaIndex}`);
      console.log('Context:');
      lines.slice(Math.max(0, georgiaIndex - 3), Math.min(lines.length, georgiaIndex + 5)).forEach(line => {
        console.log('  ' + line);
      });
    }

    // Try to get chart details through JavaScript execution
    console.log('\n\nAttempting to extract Highcharts data...');
    const chartData = await page.evaluate(() => {
      const result = {
        seriesCount: 0,
        seriesNames: [],
        dataPoints: []
      };

      // Check for Highcharts instance
      if (window.Highcharts && window.Highcharts.charts && window.Highcharts.charts.length > 0) {
        const chart = window.Highcharts.charts[0];
        if (chart && chart.series) {
          result.seriesCount = chart.series.length;

          chart.series.forEach((series, idx) => {
            result.seriesNames.push({
              index: idx,
              name: series.name,
              dataCount: series.data ? series.data.length : 0
            });

            if (series.data && series.data.length > 0) {
              // Get all data points
              series.data.forEach(point => {
                result.dataPoints.push({
                  seriesIndex: idx,
                  seriesName: series.name,
                  category: point.category,
                  x: point.x,
                  y: point.y,
                  name: point.name
                });
              });
            }
          });
        }
      }

      return result;
    });

    console.log('Highcharts data:');
    console.log(JSON.stringify(chartData, null, 2));

    // Extract years and growth rates
    const startYear = 2000;
    const endYear = 2027;
    const growthData = {};

    chartData.dataPoints.forEach(point => {
      // Try to parse year from various formats
      let year = null;
      if (point.category) {
        year = parseInt(point.category);
      } else if (point.x) {
        year = parseInt(point.x);
      } else if (point.name) {
        year = parseInt(point.name);
      }

      if (year && year >= startYear && year <= endYear && point.y !== null && point.y !== undefined) {
        growthData[year] = parseFloat(point.y);
      }
    });

    console.log('\n\nExtracted Growth Rate Data:');
    console.log(JSON.stringify(growthData, null, 2));

    // Now process Real GDP Level
    console.log('\n\n===========================================');
    console.log('Scraping Real GDP Level for Georgia...\n');

    await page.goto('https://www.imf.org/external/datamapper/NGDP_R@WEO', {
      waitUntil: 'load',
      timeout: 60000
    });
    await page.waitForTimeout(3000);

    // Search for Georgia again
    searchInput = await page.locator('input[placeholder="Search"]').first();
    if (searchInput) {
      await searchInput.click({ timeout: 5000 });
      await searchInput.fill('Georgia');
      await page.waitForTimeout(1500);

      const georgiaOption = await page.locator('text=/^Georgia$/').first();
      if (georgiaOption) {
        await georgiaOption.click();
        await page.waitForTimeout(3000);
      }
    }

    // Extract Highcharts data for GDP Level
    const chartDataLevel = await page.evaluate(() => {
      const result = {
        seriesCount: 0,
        dataPoints: []
      };

      if (window.Highcharts && window.Highcharts.charts && window.Highcharts.charts.length > 0) {
        const chart = window.Highcharts.charts[0];
        if (chart && chart.series) {
          result.seriesCount = chart.series.length;

          chart.series.forEach((series, idx) => {
            if (series.data && series.data.length > 0) {
              series.data.forEach(point => {
                result.dataPoints.push({
                  category: point.category,
                  x: point.x,
                  y: point.y,
                  name: point.name
                });
              });
            }
          });
        }
      }

      return result;
    });

    console.log('GDP Level Highcharts data:');
    console.log(JSON.stringify(chartDataLevel, null, 2));

    // Extract years and levels
    const levelData = {};
    chartDataLevel.dataPoints.forEach(point => {
      let year = null;
      if (point.category) {
        year = parseInt(point.category);
      } else if (point.x) {
        year = parseInt(point.x);
      } else if (point.name) {
        year = parseInt(point.name);
      }

      if (year && year >= startYear && year <= endYear && point.y !== null && point.y !== undefined) {
        levelData[year] = parseFloat(point.y);
      }
    });

    console.log('\n\nExtracted GDP Level Data:');
    console.log(JSON.stringify(levelData, null, 2));

    // Compile final output
    console.log('\n\n===========================================');
    console.log('FINAL COMPILATION: GEORGIA ECONOMIC DATA (2000-2027)');
    console.log('===========================================\n');

    const compiledData = [];
    console.log('Year\tReal GDP Level\tGrowth Rate (%)');
    console.log('---\t--------------\t---------------');

    for (let year = startYear; year <= endYear; year++) {
      const level = levelData[year] || null;
      const growth = growthData[year] || null;

      compiledData.push({
        year,
        real_gdp_level: level,
        growth_rate: growth
      });

      const levelStr = level !== null ? level.toFixed(2) : 'N/A';
      const growthStr = growth !== null ? growth.toFixed(2) : 'N/A';
      console.log(`${year}\t${levelStr}\t\t${growthStr}`);
    }

    // Save outputs
    const output = {
      country: 'Georgia',
      source: 'IMF World Economic Outlook (October 2025)',
      sourceUrl: 'https://www.imf.org/external/datamapper/',
      dataRange: { start: startYear, end: endYear },
