    };

    fs.writeFileSync('/root/georgia_gdp_final.json', JSON.stringify(output, null, 2));
    console.log('\n\nJSON output saved to: georgia_gdp_final.json');

    // CSV output
    let csvContent = 'Year,Real GDP Level,Growth Rate (%)\n';
    compiledData.forEach(item => {
      const level = item.real_gdp_level !== null ? item.real_gdp_level.toFixed(2) : '';
      const growth = item.growth_rate !== null ? item.growth_rate.toFixed(2) : '';
      csvContent += `${item.year},${level},${growth}\n`;
    });

    fs.writeFileSync('/root/georgia_gdp_final.csv', csvContent);
    console.log('CSV output saved to: georgia_gdp_final.csv');

  } catch (error) {
    console.error('Error:', error.message);
  } finally {
    await browser.close();
  }
}

