const { chromium } = require('playwright');
const fs = require('fs');

async function scrapeLevel() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  try {
    console.log('Trying to extract Real GDP Level for Georgia...\n');

    // Navigate directly to the Real GDP level indicator with Georgia pre-selected
    const urls = [
      'https://www.imf.org/external/datamapper/NGDP_R@WEO#countries=GEO',
      'https://www.imf.org/external/datamapper/NGDP_R@WEO?countries=GEO',
      'https://www.imf.org/external/datamapper/NGDP_R@WEO'
    ];

    for (const url of urls) {
      console.log(`Trying URL: ${url}`);
      try {
        await page.goto(url, { waitUntil: 'load', timeout: 60000 });
        await page.waitForTimeout(5000);

        // Check if page has content
        const pageTitle = await page.title();
        console.log('  Page title:', pageTitle);

        // Try searching for Georgia if not already selected
        if (!pageTitle.includes('Georgia')) {
          const searchInput = await page.locator('input[placeholder="Search"]').first();
          if (searchInput) {
            console.log('  Searching for Georgia...');
            await searchInput.click({ timeout: 3000, force: true });
            await searchInput.fill('Georgia');
            await page.waitForTimeout(1500);

            const georgiaElements = await page.locator('text=Georgia').all();
            if (georgiaElements.length > 0) {
              for (let elem of georgiaElements) {
                try {
                  await elem.click({ timeout: 3000, force: true });
                  await page.waitForTimeout(2000);
                  break;
                } catch (e) {
                  // Continue
                }
              }
            }
          }
        }

        // Extract chart data
        const levelData = await page.evaluate(() => {
          const result = { data: {}, seriesInfo: [] };

          if (window.Highcharts && window.Highcharts.charts && window.Highcharts.charts.length > 0) {
            for (let chart of window.Highcharts.charts) {
              if (chart && chart.series) {
                for (let series of chart.series) {
                  result.seriesInfo.push({
                    name: series.name,
                    dataCount: series.data ? series.data.length : 0
                  });

                  // Collect data from any series with 'GEO' or last series with data
                  if (series.data && series.data.length > 0 && (series.name === 'GEO' || series.name.includes('Georgia'))) {
                    series.data.forEach(point => {
                      if (point.category && point.y !== null && point.y !== undefined) {
                        result.data[point.category] = point.y;
                      }
                    });
                  }
                }
              }
            }
          }

          // If no specific GEO series found, try to get the last series with data
          if (Object.keys(result.data).length === 0 && window.Highcharts && window.Highcharts.charts && window.Highcharts.charts.length > 0) {
            const chart = window.Highcharts.charts[0];
            if (chart && chart.series) {
              // Look for the last series with data (should be GEO)
              for (let i = chart.series.length - 1; i >= 0; i--) {
                const series = chart.series[i];
                if (series.data && series.data.length > 0) {
                  series.data.forEach(point => {
                    if (point.category && point.y !== null && point.y !== undefined) {
                      result.data[point.category] = point.y;
                    }
                  });
                  console.log('Found data in series:', series.name);
                  break;
                }
              }
            }
          }

          return result;
        });

        console.log('  Series found:', levelData.seriesInfo.length);
        console.log('  Data points:', Object.keys(levelData.data).length);

        if (Object.keys(levelData.data).length > 0) {
          console.log('  Sample years:', Object.keys(levelData.data).slice(0, 5).join(', '));
          console.log('\nSuccessfully extracted Real GDP level data!\n');

          // Extract 2000-2027
          const extractedLevel = {};
          for (let year = 2000; year <= 2027; year++) {
            if (levelData.data[year] !== undefined) {
              extractedLevel[year] = levelData.data[year];
            }
          }

          console.log('Years 2000-2027 with data:', Object.keys(extractedLevel).length);
          if (Object.keys(extractedLevel).length > 0) {
            console.log('Sample data:');
            const years = Object.keys(extractedLevel).map(y => parseInt(y)).sort((a, b) => a - b);
            years.forEach(year => {
              console.log(`  ${year}: ${extractedLevel[year].toFixed(2)}`);
            });
          }

          await browser.close();
          return extractedLevel;
        }
      } catch (err) {
        console.log(`  Failed: ${err.message.substring(0, 50)}`);
      }
    }

    console.log('\nCould not extract Real GDP level data.');
    await browser.close();
    return {};

  } catch (error) {
    console.error('Error:', error.message);
    await browser.close();
    return {};
  }
}

